enum Tree<T> {
    Leaf(T),
    Branch {
        value: T,
        left: Box<Tree<T>>,
        right: Box<Tree<T>>,
    },
}

impl<T: std::fmt::Display> Tree<T> {
    fn depth(&self) -> usize {
        match self {
            Tree::Leaf(_) => 1,
            Tree::Branch { left, right, .. } => {
                1 + left.depth().max(right.depth())
            }
        }
    }
}

