use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};

struct Delay { remaining: u32 }

impl Future for Delay {
    type Output = String;
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context) -> Poll<String> {
        if self.remaining == 0 {
            Poll::Ready("done".to_string())
        } else {
            self.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}
